export function createBusinessExperience(){
 let zone=0,number=0,choice=-1; let vipChoice=-1;
 const panel=document.createElement('aside');panel.id='wy410BusinessPanel';
 panel.style.cssText='display:none;position:fixed;z-index:110;left:50%;bottom:max(74px,env(safe-area-inset-bottom));transform:translateX(-50%);width:min(94vw,430px);max-height:calc(100dvh - 205px);overflow-y:auto;box-sizing:border-box;background:#fffcf6;color:#263b57;border:1.5px solid #c9a76b;border-radius:15px;padding:11px 12px;box-shadow:0 9px 27px #15223966;font:13px/1.5 system-ui,sans-serif';
 document.body.append(panel);
 const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const buttonStyle='border:1px solid #d8c8ab;border-radius:8px;background:#f5efe5;color:#263b57;padding:8px 9px;font:inherit;text-align:left;cursor:pointer';
 const brand=`<div class="wy414Brand"><img src="office-logo-transparent.png" alt="德威陽官方原始Logo"><div style="flex:1;min-width:0"><b>德威陽國際法律事務所</b><small>WEI &amp; YANG INTERNATIONAL LAW FIRM</small></div><button data-act="close" aria-label="關閉" style="border:0;background:transparent;color:#50366b;font-size:22px">×</button></div>`;
 function render(){
 if(zone===6){const v=VIP[number];panel.innerHTML=`${brand}<div style="display:flex;justify-content:space-between"><b>VIP 商務偵探</b><span>${number+1} / 25</span></div><h3>${escape(v.title)}</h3><p>以下四項契約條款，哪一項法律風險最大？</p><div style="display:grid;gap:7px">${v.clauses.map((c,i)=>`<button data-act="choice" data-i="${i}" style="${buttonStyle}">${i+1}. ${escape(c)}</button>`).join('')}</div>${vipChoice>=0?`<div class="wy414Analysis"><b>${vipChoice===v.correct?'答對了！':'再找找看：'}</b> ${vipChoice===v.correct?escape(v.explanation):'注意哪一項讓一方承擔不合理或無限制的義務？可以重新選擇。'}</div>`:''}<div style="display:flex;justify-content:space-between;gap:7px;margin-top:10px"><button data-act="prev" style="${buttonStyle}">‹ 上一則</button><button data-act="reset" style="${buttonStyle}">返回</button><button data-act="next" style="${buttonStyle}">下一則 ›</button></div>`;return;}
 const z=DATA[zone],story=z.stories[number];let explanation='',service='';if(choice>=0){const raw=String(story.choices[choice][1]);const split=raw.split(/德威陽可以做什麼[？?]/);explanation=split[0].trim();service=(split.slice(1).join('')||story.closing||'協助檢視相關文件、評估法律風險及規劃爭議處理策略。').trim()}
 panel.innerHTML=`${brand}<div style="display:flex;justify-content:space-between;color:#75558d;font-size:12px"><span>${escape(z.name)}</span><span>${number+1} / 25</span></div><h3 style="margin:9px 0">${escape(story.title)}</h3><p>${escape(story.story)}</p><div style="display:grid;gap:7px">${story.choices.map((c,i)=>`<button data-act="choice" data-i="${i}" style="${buttonStyle}">${escape(c[0])}　›</button>`).join('')}</div>${choice>=0?`<div class="wy414Analysis">${escape(explanation)}</div><section class="wy414Service"><strong>德威陽可以做什麼？</strong><p>${escape(service)}</p></section>`:''}<div style="display:flex;justify-content:space-between;gap:7px;margin-top:12px"><button data-act="prev" style="${buttonStyle}">‹ 上一則</button><button data-act="reset" style="${buttonStyle}">返回</button><button data-act="next" style="${buttonStyle}">下一則 ›</button></div>`;
 }
 panel.addEventListener('click',e=>{const b=e.target.closest('button[data-act]');if(!b)return;const a=b.dataset.act;if(a==='close'){panel.style.display='none';return;}if(a==='choice'){if(zone===6)vipChoice=Number(b.dataset.i);else choice=Number(b.dataset.i);}if(a==='next'){number=(number+1)%25;choice=-1;vipChoice=-1;}if(a==='prev'){number=(number+24)%25;choice=-1;vipChoice=-1;}if(a==='reset'){choice=-1;vipChoice=-1;}render();});
 return {open(i){zone=i;number=0;choice=-1;vipChoice=-1;render();panel.style.display='block'},hide(){panel.style.display='none'},get count(){return DATA.reduce((s,z)=>s+z.stories.length,0)+VIP.length}};
}
